**Special Case - DeepSeek Parser**:

**File**: `sgl-router/src/tool_parser/parsers/deepseek_parser.rs`

DeepSeek uses a wrapper structure where ALL tool calls are wrapped in outer tags, with individual calls separated. It **must override** `build_structural_tag()` because it needs `tags_with_separator` format.

```rust
impl ToolParser for DeepSeekParser {
    fn get_format_info(&self, tool_name: &str) -> (String, String, String) {
        // Not used for structural tag (overridden), but needed for parsing
        let begin = "<｜tool▁call▁begin｜>\n```jsonc\n{".to_string();
        let end = "}\n```\n<｜tool▁call▁end｜>".to_string();
        let trigger = "<｜tool▁calls▁begin｜>".to_string();
        (begin, end, trigger)
    }

    // MUST override because DeepSeek uses wrapper + separator format
    fn build_structural_tag(
        &self,
        tools: &[Tool],
        at_least_one: bool,
        stop_after_first: bool,
    ) -> Result<String, String> {
        // Build individual tool call tags (WITHOUT outer wrapper)
        let mut tool_tags = Vec::new();

        for tool in tools {
            let name = &tool.function.name;
            let schema = tool.function.parameters.clone().unwrap_or_default();

            tool_tags.push(json!({
                "format": "tag",
                "begin": "<｜tool▁call▁begin｜>\n```jsonc\n{",
                "content": {
                    "format": "json_schema",
                    "schema": schema
                },
                "end": "}\n```\n<｜tool▁call▁end｜>"
            }));
        }

        // Wrap ALL tool calls in outer tag with separator
        let structural_tag = json!({
            "format": "triggered_tags",
            "triggers": ["<｜tool▁calls▁begin｜>"],
            "tags": [{
                "format": "tag",
                "begin": "<｜tool▁calls▁begin｜>\n",
                "content": {
                    "format": "tags_with_separator",
                    "tags": tool_tags,
                    "separator": "\n",
                    "at_least_one": at_least_one,
                    "stop_after_first": stop_after_first
                },
                "end": "\n<｜tool▁calls▁end｜>"
            }],
            "at_least_one": false,  // Outer level
            "stop_after_first": false
        });

        serde_json::to_string(&structural_tag)
            .map_err(|e| format!("Failed to serialize structural tag: {}", e))
    }
}
```

### 3. Add Constraint Generation to Tool Parsers Module

**File**: `sgl-router/src/routers/grpc/utils.rs`

**REMOVE**: `generate_tool_constraints()` (old implementation, will be replaced)

**File**: `sgl-router/src/tool_parser/constraints.rs` (NEW FILE)

**ADD**: Constraint generation logic in tool_parsers module (cleaner architecture)

```rust
use crate::tool_parser::factory::ToolParserFactory;
use crate::tool_parser::traits::ToolParser;

/// Build tool call constraint based on tool_choice and parallel_tool_calls.
///
/// This function follows the same pattern as `get_tool_parser()`:
/// - Respects user's explicit --tool-call-parser flag (configured_parser)
/// - Falls back to auto-detection by model name
///
/// Strategy:
/// - tool_choice="auto": Use structural_tag from parser (if available)
/// - tool_choice="required": Use json_schema
/// - tool_choice=specific function: Use json_schema
///
/// Args:
///     tools: Available tools
///     tool_choice: Tool choice mode
///     parallel_tool_calls: Whether to allow multiple tool calls
///     tool_parser_factory: Factory to get parser (from SharedComponents)
///     configured_parser: User's explicit --tool-call-parser choice (from processor's configured_tool_parser)
///     model: Model name for auto-detection fallback
///
/// Returns:
///     Option<(constraint_type, constraint_value)>
pub fn build_tool_call_constraint(
    tools: &[Tool],
    tool_choice: &Option<ToolChoice>,
    parallel_tool_calls: bool,
    tool_parser_factory: &ToolParserFactory,
    configured_parser: Option<&String>,
    model: &str,
) -> Result<Option<(String, String)>, String> {
    let Some(choice) = tool_choice.as_ref() else {
        return Ok(None);
    };

    match choice {
        // Auto mode: Use structural tag if parser supports it
        ToolChoice::Value(ToolChoiceValue::Auto) => {
            // Get parser using same pattern as get_tool_parser()
            // This respects --tool-call-parser flag with auto-detection fallback
            let parser = get_tool_parser(tool_parser_factory, configured_parser, model);

            // Build structural tag
            let tag = parser.build_structural_tag(
                tools,
                false,  // at_least_one = false for auto
                !parallel_tool_calls  // stop_after_first = !parallel_tool_calls
            )?;
            Ok(Some(("structural_tag".to_string(), tag)))
        }

        // Required mode: Use json_schema
        ToolChoice::Value(ToolChoiceValue::Required) => {
            let schema = build_required_json_schema(tools, parallel_tool_calls)?;
            Ok(Some(("json_schema".to_string(), schema)))
        }

        // Specific function: Use json_schema for that function
        ToolChoice::Function { .. } => {
            if tools.is_empty() {
                return Ok(None);
            }
            let schema = build_specific_function_json_schema(&tools[0], parallel_tool_calls)?;
            Ok(Some(("json_schema".to_string(), schema)))
        }

        // AllowedTools with required mode
        ToolChoice::AllowedTools { mode, .. } => {
            if mode == "required" {
                let schema = build_required_json_schema(tools, parallel_tool_calls)?;
                Ok(Some(("json_schema".to_string(), schema)))
            } else {
                // Auto mode - try structural tag
                let parser = get_tool_parser(tool_parser_factory, configured_parser, model);
                let tag = parser.build_structural_tag(tools, false, !parallel_tool_calls)?;
                Ok(Some(("structural_tag".to_string(), tag)))
            }
        }

        // None mode or unknown
        _ => Ok(None),
    }
}

/// Build JSON schema for required tool choice mode.
fn build_required_json_schema(
    tools: &[Tool],
    parallel_tool_calls: bool,
) -> Result<String, String> {
    let mut any_of_schemas = Vec::new();
    for tool in tools {
        let tool_schema = json!({
            "properties": {
                "name": {
                    "type": "string",
                    "enum": [tool.function.name]
                },
                "parameters": tool.function.parameters
            },
            "required": ["name", "parameters"]
        });
        any_of_schemas.push(tool_schema);
    }

    // Consolidate $defs from all tools
    let mut all_defs: HashMap<String, Value> = HashMap::new();
    for tool in tools {
        if let Value::Object(params) = &tool.function.parameters {
            if let Some(Value::Object(defs)) = params.get("$defs") {
                for (def_name, def_schema) in defs {
                    if let Some(existing) = all_defs.get(def_name) {
                        if existing != def_schema {
                            return Err(format!(
                                "Tool definition '{}' has conflicting schemas",
                                def_name
                            ));
                        }
                    } else {
                        all_defs.insert(def_name.clone(), def_schema.clone());
                    }
                }
            }
        }
    }

    // Build array schema
    let mut array_schema = json!({
        "type": "array",
        "minItems": 1,
        "items": {
            "type": "object",
            "anyOf": any_of_schemas
        }
    });

    // Add maxItems if parallel_tool_calls is false
    if !parallel_tool_calls {
        array_schema["maxItems"] = json!(1);
    }

    // Add $defs if any
    if !all_defs.is_empty() {
        array_schema["$defs"] = json!(all_defs);
    }

    serde_json::to_string(&array_schema)
        .map_err(|e| format!("Failed to serialize json schema: {}", e))
}

/// Build JSON schema for specific function choice.
fn build_specific_function_json_schema(
    tool: &Tool,
    _parallel_tool_calls: bool,  // Always single for specific function
) -> Result<String, String> {
    let schema = json!({
        "type": "array",
        "minItems": 1,
        "maxItems": 1,  // Always single for specific function
        "items": {
            "properties": {
                "name": {
                    "type": "string",
                    "enum": [tool.function.name]
                },
                "parameters": tool.function.parameters
            },
            "required": ["name", "parameters"]
        }
    });

    serde_json::to_string(&schema)
        .map_err(|e| format!("Failed to serialize json schema: {}", e))
}
```

